import type { Article, ArticleSource } from "./article-data";
import type { Locale, PageKey } from "./site-data";

export type TrustArticleKey = Extract<PageKey, "legitArticle" | "reviewsArticle" | "safeArticle" | "scamClaimsArticle" | "helpCenterArticle" | "copycatArticle" | "policyTrackerArticle">;

type Brief = {
  title: string; tag: string; lede: string; subject: string; query: string;
  thesis: string; positive: string; caution: string; primary: string;
  test: string; record: string; decision: string; sources: ArticleSource[];
};

const official = {
  home: { label: "Kakobuy official homepage", url: "https://www.kakobuy.com/" },
  guide: { label: "Kakobuy official beginner guide", url: "https://www.kakobuy.com/index/information?information_id=12" },
  fees: { label: "Kakobuy official Services & Fees page", url: "https://www.kakobuy.com/service/help/question?id=63" },
  returns: { label: "Kakobuy official return and exchange page", url: "https://www.kakobuy.com/service/help/question?id=51" },
  agreement: { label: "Kakobuy registration and account agreement", url: "https://www.kakobuy.com/service/help/question?cid=63&id=40" },
  estimate: { label: "Kakobuy official shipping estimator", url: "https://www.kakobuy.com/tools/estimate" },
  notice: { label: "Kakobuy official notices", url: "https://www.kakobuy.com/index/notice" },
  app: { label: "Kakobuy iOS App Store listing", url: "https://apps.apple.com/us/app/kakobuy/id6501974361" },
};

function sections(locale: Locale, b: Brief): Article["sections"] {
  if (locale === "de") return [
    [`Die Suchfrage richtig einordnen`, [`Wer nach „${b.query}“ sucht, möchte meist ein schnelles Ja oder Nein. Eine belastbare Prüfung von ${b.subject} braucht jedoch eine klarere Frage: Welche öffentlich überprüfbaren Belege sind aktuell vorhanden, welche Erfahrung ist nur ein Einzelfall und welche Unsicherheit bleibt bestehen? ${b.thesis} Das Ergebnis ist eine datierte Einschätzung, kein dauerhaftes Gütesiegel.`, `Wir trennen Plattformidentität, veröffentlichte Bedingungen, Transaktionsablauf und Nutzerergebnis. Ein richtiger Domainname beweist nicht die Qualität jedes Verkäufers; eine schlechte Einzelerfahrung widerlegt nicht jede Funktion. Diese Trennung verhindert, dass ein auffälliger Screenshot, eine Sternezahl oder eine Werbeaussage mehr Gewicht erhält, als die Quelle tragen kann.`]],
    [`Primärquellen zuerst`, [`Beginne mit ${b.primary}. Öffentliche Hilfeseiten zeigen, welche Leistung die Plattform selbst beschreibt; der Live-Checkout oder Kontostatus zeigt, was für eine konkrete Transaktion angeboten wird. ${b.positive} Speichere Seitentitel, vollständige URL und Zugriffsdatum, damit eine spätere Änderung erkennbar bleibt.`, `Suchergebnisse, Videos, Foren und soziale Posts sind Hinweise, aber keine Ersatzquelle für aktuelle Bedingungen. Prüfe, ob sie auf eine erreichbare Originalseite verweisen und ob Datum, Region und Produktart vergleichbar sind. Fehlt der Primärbeleg, muss die Schlussfolgerung enger werden, statt die Lücke mit Wiederholungen anderer Beiträge zu füllen.`]],
    [`Positive und negative Signale gleich prüfen`, [`Positive Signale sind nur dann nützlich, wenn sie konkret sind: eine erreichbare offizielle Seite, ein nachvollziehbarer Ablauf, ein datierter Status oder eine dokumentierte Reaktion. ${b.positive} Auch gute Signale gelten nur für ihren Umfang und belegen weder Authentizität eines Produkts noch eine garantierte Lieferzeit.`, `Negative Signale brauchen dieselbe Disziplin. ${b.caution} Frage, ob das Material vollständig ist, ob eine Bestellnummer oder private Daten entfernt werden müssen und ob Plattform, Verkäufer, Zahlungsdienst oder Frachtführer für den beobachteten Schritt zuständig war. Eine faire Analyse beschreibt das Ereignis, ohne eine unbewiesene Ursache zu erfinden.`]],
    [`Den Ablauf statt eines Schlagworts testen`, [`Der praktische Test lautet: ${b.test}. Führe nur reversible Schritte aus, bis Domain, Preisbestandteile, Option und Bedingungen verständlich sind. Bei Warnmeldungen, unerwarteten Weiterleitungen, Zeitdruck oder Forderungen nach fremden Geheimnissen stoppen und über die selbst eingegebene offizielle Startseite neu beginnen.`, `Bei einer echten Bestellung entstehen mehrere getrennte Entscheidungen: Produktkauf, Lagereingang und QC, After-Sales, Paketbildung und internationaler Versand. Dokumentiere jede Stufe getrennt. So lässt sich ein Problem genauer zuordnen und eine pauschale Aussage wird nicht aus einem einzigen Teil des Ablaufs abgeleitet.`]],
    [`Belege vergleichbar machen`, [`${b.record} Ein guter Datensatz nennt Datum, Land oder Region, Artikelart, Bestellphase, sichtbare Kosten, Statuswechsel und Ergebnis. Private Angaben, Adressen, Codes, Cookies, Zahlungsdaten und vollständige Bestellnummern gehören nicht in eine öffentliche Auswertung.`, `Bewertungen werden erst vergleichbar, wenn dieselbe Frage gemessen wird. Lieferdauer ist nicht Supportqualität; Verkäuferqualität ist nicht Plattformidentität; eine Versandlinie ist nicht das gesamte System. Zähle keine mehrfach kopierte Geschichte als mehrere unabhängige Fälle und gewichte detailreiche, datierte Belege höher als eine Behauptung ohne überprüfbaren Kontext.`]],
    [`Zeit, Region und Version beachten`, [`Plattformseiten, Gebühren, verfügbare Zahlungswege, Versandlinien und App-Funktionen können sich ändern. Eine Quelle ohne Datum kann bei Veröffentlichung korrekt gewesen sein und heute trotzdem die falsche Entscheidung fördern. Prüfe veränderliche Angaben unmittelbar vor Zahlung oder Paketeinreichung erneut und behandle ältere Screenshots als historischen Kontext.`, `Regionen sehen nicht immer dieselben Optionen. Ein Bericht aus einem anderen Zielland oder einer älteren App-Version ist nicht automatisch falsch, aber möglicherweise nicht übertragbar. Notiere die Grenze offen. Wo die Live-Seite nicht zugänglich oder der Wortlaut unvollständig ist, sage „nicht verifiziert“ statt aus einem ähnlichen Fall Gewissheit abzuleiten.`]],
    [`Risiko vorab begrenzen`, [`Nutze einen einzigartigen Zugang, die verfügbaren Kontoschutzfunktionen und einen Zahlungsweg mit klaren Aufzeichnungen. Beginne bei Unsicherheit mit einer kleinen, unkomplizierten Transaktion, deren Verlust du tragen kannst. Prüfe Optionen und Verkäuferbedingungen vor Zahlung und fordere nur entscheidungsrelevante QC-Belege an.`, `Lege ein eigenes Budget und eine Frist fest. Produktpreis, Inlandsversand, Zahlungsgebühr, Zusatzdienste und internationale Fracht sind getrennte Ebenen. Entscheide nicht unter Countdown-Druck und verschicke keine Codes an angeblichen Support. Diese Kontrollen beweisen keine Sicherheit, reduzieren aber vermeidbare Fehler und verbessern die spätere Nachvollziehbarkeit.`]],
    [`Wann die Prüfung abgebrochen wird`, [`Stoppe, wenn Domain oder Zertifikat nicht passen, ein Link durch unerklärte Hosts springt, die angeforderte Aktion nicht zum Seitentyp passt oder die behauptete Regel auf keiner aktuellen offiziellen Seite auffindbar ist. Probiere keine Zugangsdaten aus, um Zweifel zu lösen. Nutze einen bekannten Supportweg und teile nur die für die Klärung nötigen Informationen.`, `Auch widersprüchliche Statusangaben, nicht erklärte Zusatzkosten oder ein ablaufendes After-Sales-Fenster verlangen eine Pause. Sichere den aktuellen Stand, formuliere die konkrete Abweichung und frage nach einer schriftlichen Erklärung. Eine ungelöste Unsicherheit ist selbst eine Entscheidungstatsache; sie darf nicht durch ein optimistisches Versprechen ersetzt werden.`]],
    [`Datierte Schlussfolgerung`, [`${b.decision} Diese Aussage gilt für die am 21. September 2026 geprüften öffentlichen Quellen. Sie ist weder Kaufempfehlung noch Garantie für Verkäufer, Produkt, Zoll, Support oder Zustellung. Der Nutzen liegt in der nachvollziehbaren Begründung und in den klar benannten Grenzen.`, `Wiederhole die Kerntests vor einer sensiblen Aktion: Domain selbst öffnen, aktuelle Bedingung lesen, Kostenstapel prüfen, Bestelldaten sichern und Ergebnis datieren. Wenn neue Belege auftauchen, ändere die Schlussfolgerung nur im Umfang der beobachteten Änderung. So bleibt der Artikel aktuell, ohne aus jeder Meldung ein neues endgültiges Urteil zu machen.`]],
  ];
  if (locale === "es") return [
    [`Definir bien la búsqueda`, [`Quien busca «${b.query}» suele querer un sí o no inmediato. Una revisión sólida de ${b.subject} exige separar pruebas públicas actuales, experiencias individuales e incertidumbre. ${b.thesis} El resultado es una evaluación fechada, no un sello permanente.`, `Separamos identidad de la plataforma, términos publicados, flujo de la transacción y resultado del usuario. El dominio correcto no demuestra la calidad de cada vendedor, y una mala experiencia aislada no invalida todas las funciones. Así una captura, una puntuación o una promesa comercial no recibe más peso del que admite su fuente.`]],
    [`Empezar por fuentes primarias`, [`Parte de ${b.primary}. La ayuda pública explica lo que la propia plataforma afirma; el checkout y el estado de cuenta muestran qué se ofrece en una operación concreta. ${b.positive} Guarda título, URL completa y fecha para detectar cambios.`, `Buscadores, vídeos, foros y redes aportan pistas, no sustituyen condiciones vigentes. Comprueba si enlazan al original y si fecha, región y tipo de producto son comparables. Sin prueba primaria, reduce el alcance de la conclusión en lugar de rellenar el hueco con repeticiones.`]],
    [`Examinar señales favorables y adversas`, [`Una señal favorable debe ser concreta: página oficial accesible, proceso trazable, estado fechado o respuesta documentada. ${b.positive} Incluso así, solo prueba su propio alcance; no certifica autenticidad ni entrega futura.`, `Aplica el mismo rigor a lo negativo. ${b.caution} Comprueba si el material está completo y qué parte —plataforma, vendedor, pago o transportista— controlaba el paso observado. Describe el hecho sin inventar una causa.`]],
    [`Probar el proceso`, [`La prueba práctica es: ${b.test}. Mantén los pasos reversibles hasta entender dominio, precio, opción y condiciones. Si aparece una alerta, redirección extraña, urgencia o petición de secretos, detente y vuelve desde la portada oficial escrita por ti.`, `Una compra contiene decisiones separadas: artículo, llegada y QC, posventa, paquete y transporte internacional. Documenta cada etapa por separado. Así se asigna mejor un problema y no se convierte un solo incidente en una conclusión sobre todo el servicio.`]],
    [`Crear evidencia comparable`, [`${b.record} Un registro útil incluye fecha, país, tipo de artículo, fase, costes visibles, cambios de estado y resultado. Elimina direcciones, códigos, cookies, pagos y números completos antes de compartir.`, `Compara la misma variable: plazo no es soporte, vendedor no es plataforma y una línea no es todo el sistema. No cuentes una historia copiada como casos independientes. Da más peso a pruebas fechadas y detalladas que a afirmaciones sin contexto.`]],
    [`Controlar fecha, región y versión`, [`Páginas, comisiones, pagos, rutas y funciones de la app cambian. Una fuente antigua puede haber sido correcta y hoy inducir a error. Revisa la condición viva antes de pagar o enviar y usa capturas antiguas solo como historial.`, `Una región puede mostrar opciones distintas. Un relato de otro país o versión no es falso por ello, pero quizá no sea transferible. Si la página no se puede leer completa, indica «no verificado» en lugar de adivinar.`]],
    [`Limitar el riesgo`, [`Usa contraseña única, protecciones disponibles y un pago con registro claro. Si dudas, empieza con una operación pequeña y sencilla. Confirma variante y vendedor antes de pagar y solicita solo evidencia QC que pueda cambiar la decisión.`, `Fija presupuesto y plazo propios. Producto, envío nacional, canal de pago, extras y transporte internacional son capas distintas. No actúes por cuenta atrás ni compartas códigos con supuesto soporte. Son controles de reducción, no una garantía.`]],
    [`Motivos para detenerse`, [`Detente si dominio o certificado no coinciden, hay saltos inexplicados, la acción no corresponde a la página o la regla no aparece en una fuente oficial actual. No pruebes credenciales para resolver la duda; usa un soporte conocido y comparte lo mínimo.`, `Estados contradictorios, cargos sin explicar o una ventana posventa que vence también exigen pausa. Guarda el estado, formula la diferencia exacta y pide explicación escrita. La incertidumbre no resuelta forma parte de la decisión.`]],
    [`Conclusión fechada`, [`${b.decision} Se basa en fuentes públicas revisadas el 21 de septiembre de 2026 y no garantiza vendedor, producto, aduana, soporte o entrega. Su valor está en el razonamiento y los límites visibles.`, `Antes de una acción sensible repite dominio, condición actual, costes y registro. Si aparece nueva evidencia, cambia la conclusión solo en la medida observada. Así el artículo sigue siendo útil sin convertir cada noticia en un veredicto definitivo.`]],
  ];
  if (locale === "fr") return [
    [`Formuler la bonne recherche`, [`La recherche « ${b.query} » appelle souvent un oui ou non. Une analyse solide de ${b.subject} sépare pourtant les preuves publiques actuelles, les expériences isolées et l’incertitude. ${b.thesis} Le résultat est une évaluation datée, pas un label permanent.`, `Nous séparons identité de la plateforme, conditions publiées, déroulement de transaction et résultat utilisateur. Le bon domaine ne prouve pas chaque vendeur ; un mauvais cas n’annule pas toutes les fonctions. Une capture, une note ou une promesse ne vaut donc pas plus que sa source.`]],
    [`Commencer par les sources primaires`, [`Partez de ${b.primary}. L’aide publique montre ce que la plateforme déclare ; le paiement et le compte montrent l’offre applicable à une opération. ${b.positive} Conservez titre, URL complète et date afin de repérer une modification.`, `Recherche, vidéos, forums et réseaux fournissent des pistes, pas les conditions actuelles. Vérifiez le lien original ainsi que date, région et produit. Sans preuve primaire, réduisez la conclusion au lieu de remplir le vide avec des répétitions.`]],
    [`Traiter les signaux de façon symétrique`, [`Un signal favorable doit être concret : page officielle accessible, parcours traçable, statut daté ou réponse documentée. ${b.positive} Il reste limité à sa portée et ne certifie ni authenticité ni livraison future.`, `Appliquez la même rigueur au négatif. ${b.caution} Identifiez si plateforme, vendeur, paiement ou transporteur contrôlait l’étape observée. Décrivez le fait sans inventer sa cause.`]],
    [`Tester le parcours`, [`Le test pratique est : ${b.test}. Gardez les actions réversibles tant que domaine, prix, option et règle ne sont pas compris. Alerte, redirection étrange, urgence ou demande de secret imposent un retour à l’accueil officiel saisi manuellement.`, `Une commande contient plusieurs décisions : article, arrivée et QC, après-vente, colis et transport. Documentez chaque étape séparément. Un incident sera mieux attribué et ne deviendra pas un jugement abusif sur tout le service.`]],
    [`Produire des preuves comparables`, [`${b.record} Un dossier utile indique date, pays, type d’article, phase, coûts visibles, changements d’état et résultat. Retirez adresses, codes, cookies, paiements et numéros complets avant partage.`, `Comparez la même variable : délai, support, vendeur, plateforme et ligne de transport ne sont pas interchangeables. Ne comptez pas une histoire copiée comme plusieurs cas. Privilégiez le détail daté au récit sans contexte.`]],
    [`Tenir compte du temps et de la région`, [`Pages, frais, paiements, lignes et fonctions d’application évoluent. Une ancienne source peut avoir été correcte mais induire aujourd’hui en erreur. Relisez la règle en direct avant paiement ou expédition.`, `Les options varient selon les destinations et versions. Un rapport étranger n’est pas faux, mais peut être non transposable. Si le texte complet reste inaccessible, notez « non vérifié » au lieu de supposer.`]],
    [`Réduire le risque avant d’agir`, [`Utilisez un mot de passe unique, les protections proposées et un paiement traçable. En cas de doute, commencez petit. Confirmez variante et vendeur avant paiement et ne demandez que les preuves QC capables de changer la décision.`, `Fixez budget et échéance. Produit, transport local, paiement, options et fret international sont distincts. Refusez le compte à rebours et ne partagez aucun code avec un prétendu support. Ces mesures réduisent le risque sans garantir le résultat.`]],
    [`Savoir s’arrêter`, [`Arrêtez si domaine ou certificat diffère, si le lien traverse des hôtes inexpliqués, si l’action ne correspond pas à la page ou si la règle actuelle est introuvable. N’essayez pas vos identifiants ; revenez à un support connu et partagez le minimum.`, `Statuts contradictoires, frais inexpliqués ou fenêtre d’après-vente proche exigent aussi une pause. Enregistrez l’état, formulez l’écart précis et demandez une réponse écrite. L’incertitude non résolue appartient à la décision.`]],
    [`Conclusion datée`, [`${b.decision} Cette conclusion repose sur les sources publiques vérifiées le 21 septembre 2026 ; elle ne garantit ni vendeur, produit, douane, support ou livraison. Sa valeur vient de sa méthode et de ses limites.`, `Avant toute action sensible, recommencez domaine, règle, coûts et enregistrement. Une nouvelle preuve ne doit modifier la conclusion qu’à hauteur du changement observé. Le contenu reste ainsi actuel sans transformer chaque signal en verdict définitif.`]],
  ];
  if (locale === "it") return [
    [`Definire la ricerca`, [`Chi cerca “${b.query}” spesso vuole un sì o un no. Una verifica solida di ${b.subject} deve invece separare prove pubbliche attuali, esperienze individuali e incertezza. ${b.thesis} Il risultato è una valutazione datata, non un marchio permanente.`, `Separiamo identità della piattaforma, termini pubblicati, flusso della transazione e risultato dell’utente. Il dominio corretto non prova ogni venditore; un singolo caso negativo non annulla ogni funzione. Screenshot, stelle o promesse non ricevono più peso di quanto consenta la fonte.`]],
    [`Partire dalle fonti primarie`, [`Inizia da ${b.primary}. L’assistenza pubblica mostra ciò che la piattaforma dichiara; checkout e account mostrano cosa vale per una transazione. ${b.positive} Salva titolo, URL completo e data per riconoscere cambiamenti.`, `Ricerca, video, forum e social sono indizi, non sostituti dei termini correnti. Verifica il collegamento originale e se data, regione e prodotto sono comparabili. Senza prova primaria, limita la conclusione invece di riempire il vuoto con ripetizioni.`]],
    [`Valutare segnali positivi e negativi`, [`Un segnale favorevole deve essere concreto: pagina ufficiale accessibile, percorso tracciabile, stato datato o risposta documentata. ${b.positive} Resta limitato al proprio ambito e non certifica autenticità o consegna futura.`, `Usa lo stesso rigore per il negativo. ${b.caution} Individua se piattaforma, venditore, pagamento o vettore controllava la fase osservata. Descrivi il fatto senza inventarne la causa.`]],
    [`Provare il processo`, [`Il test pratico è: ${b.test}. Mantieni reversibili i passaggi finché dominio, prezzo, variante e condizioni non sono chiari. Avvisi, redirect insoliti, urgenza o richieste di segreti impongono di tornare alla homepage ufficiale digitata.`, `Un ordine contiene decisioni separate: articolo, arrivo e QC, post-vendita, pacco e trasporto internazionale. Documenta ogni fase. Un problema sarà attribuito meglio e non diventerà un giudizio scorretto sull’intero servizio.`]],
    [`Rendere confrontabili le prove`, [`${b.record} Un registro utile indica data, paese, tipo di articolo, fase, costi visibili, cambi di stato e risultato. Rimuovi indirizzi, codici, cookie, pagamenti e numeri completi prima di condividere.`, `Confronta la stessa variabile: tempo, supporto, venditore, piattaforma e linea non sono equivalenti. Non contare una storia copiata come casi indipendenti. Dai più peso a prove datate e dettagliate.`]],
    [`Considerare tempo, regione e versione`, [`Pagine, commissioni, pagamenti, rotte e funzioni dell’app cambiano. Una vecchia fonte poteva essere corretta ma oggi fuorviante. Ricontrolla il termine live prima di pagare o spedire.`, `Le opzioni possono variare per destinazione e versione. Un rapporto estero non è falso, ma forse non è trasferibile. Se il testo completo non è accessibile, scrivi “non verificato” invece di indovinare.`]],
    [`Limitare il rischio`, [`Usa password unica, protezioni disponibili e un pagamento tracciabile. Nel dubbio, inizia con un’operazione piccola. Conferma variante e venditore prima del pagamento e chiedi solo prove QC decisive.`, `Fissa budget e scadenza. Prodotto, consegna interna, pagamento, servizi e spedizione internazionale sono livelli diversi. Non agire sotto conto alla rovescia e non inviare codici a un presunto supporto. Questi controlli riducono il rischio, non garantiscono l’esito.`]],
    [`Quando fermarsi`, [`Fermati se dominio o certificato differiscono, se ci sono passaggi inspiegati, se l’azione non corrisponde alla pagina o se il termine attuale non è rintracciabile. Non provare credenziali; torna a un supporto noto e condividi il minimo.`, `Stati contraddittori, costi non spiegati o una finestra post-vendita in scadenza richiedono pausa. Salva lo stato, descrivi la differenza e chiedi risposta scritta. L’incertezza irrisolta fa parte della decisione.`]],
    [`Conclusione datata`, [`${b.decision} La conclusione usa fonti pubbliche verificate il 21 settembre 2026 e non garantisce venditore, prodotto, dogana, supporto o consegna. Il valore è nella motivazione e nei limiti.`, `Prima di un’azione sensibile ripeti controllo del dominio, regola, costi e registro. Nuove prove devono cambiare il giudizio solo nella misura osservata. L’articolo resta così utile senza trasformare ogni segnale in verdetto finale.`]],
  ];
  return [
    [`Define what the search is really asking`, [`A search for “${b.query}” usually asks for a fast yes-or-no answer. A defensible review of ${b.subject} needs a narrower question: what current public evidence can be verified, what is merely one person’s experience, and what remains unknown? ${b.thesis} The result should be a dated assessment with conditions, not a permanent badge or a promise about every future transaction.`, `Keep platform identity, published terms, transaction flow and user outcome separate. A correct domain does not prove the quality of every marketplace seller. One failed parcel does not show that every platform function failed. One successful order does not guarantee the next one. This separation prevents a dramatic screenshot, star rating or marketing phrase from carrying more weight than its source can support.`]],
    [`Start with first-party evidence`, [`Begin with ${b.primary}. Public help pages show what the platform says it offers; the live checkout and account state show what is actually presented for a specific transaction. ${b.positive} Save the page title, complete URL and access date. That small record makes it possible to distinguish a later policy change from a mistaken quotation or an old cached page.`, `Search results, videos, forums and social posts can reveal questions worth investigating, but they do not replace current terms. Check whether they link to an accessible original and whether date, destination, product type and order stage are comparable. If the primary wording cannot be found, narrow the conclusion rather than filling the gap with repeated claims from other summaries.`]],
    [`Test favorable and unfavorable signals the same way`, [`A favorable signal should be concrete: an accessible official page, a traceable flow, a dated status update, or a documented support response. ${b.positive} Even strong positive evidence is limited to its scope. It does not authenticate a marketplace product, guarantee a route, or show how every seller and payment channel will behave.`, `Negative reports deserve the same discipline. ${b.caution} Check whether the available material is complete and whether the platform, seller, payment provider or carrier controlled the step that failed. A fair investigation describes the observed event and its owner without inventing motive, suppressing inconvenient evidence, or turning an unresolved dispute into a proven universal claim.`]],
    [`Test the process, not the label`, [`The practical test is: ${b.test}. Keep steps reversible until the domain, selected option, visible cost layers and relevant conditions make sense. Stop at browser warnings, unexplained redirects, artificial urgency or requests for secrets unrelated to the task. Restart from the official homepage that you typed yourself rather than using the link that created the concern.`, `A real order contains several independent decisions: the product purchase, warehouse arrival and QC, after-sales eligibility, parcel creation and international carriage. Record each stage separately. That makes a problem easier to attribute and prevents a conclusion about one seller, one route or one support conversation from being mislabeled as a conclusion about the whole service.`]],
    [`Turn reports into comparable evidence`, [`${b.record} A useful record states the date, destination country, item type, order stage, visible cost, status changes and outcome. Remove names, addresses, verification codes, cookies, payment details, QR codes and full order numbers before anything is shared publicly. Privacy-safe evidence is more useful than an unredacted screenshot that exposes the customer and still omits the relevant URL.`, `Compare the same variable across cases. Delivery speed is not support quality; seller quality is not platform identity; one shipping line is not the whole system. Do not count the same copied story as multiple independent reports. Give more weight to specific, dated records with a consistent timeline than to a confident sentence with no route, region, order stage or source.`]],
    [`Account for date, region and version`, [`Help pages, fees, payment methods, shipping routes and app features can change. An undated source may have been accurate when published and still lead to a wrong decision today. Recheck every variable term immediately before payment or parcel submission. Use older screenshots as historical context, not as instructions, and never silently combine observations from different dates into one supposedly current policy.`, `Regions and app versions may expose different choices. A report from another destination is not automatically false, but it may not transfer to your account. State that limit. When a page needs sign-in or JavaScript and the complete wording cannot be inspected, mark the point as unverified. Honest uncertainty is more useful than a precise conclusion assembled from a similar but different case.`]],
    [`Reduce exposure before the first order`, [`Use a unique password, every account-protection option currently offered, and a payment method that produces clear records. If uncertainty remains, begin with a small and uncomplicated transaction whose loss you could absorb. Confirm the seller option and restrictions before paying, then request only warehouse evidence that could genuinely change the accept-or-return decision.`, `Set your own budget and deadline. Product price, domestic delivery, payment-channel cost, optional services and international freight are different layers. Do not act because a countdown or message says an opportunity will disappear. Never send login codes or full payment credentials to somebody claiming to be support. These controls cannot prove safety, but they reduce preventable errors and preserve evidence.`]],
    [`Know when the review should stop the transaction`, [`Stop if the hostname or certificate is wrong, a link jumps through unexplained hosts, the requested action does not match the page type, or the claimed rule cannot be located on a current official page. Do not test credentials to resolve the doubt. Return to the typed homepage, use a known support channel, and share only the minimum information needed to describe the URL or order state.`, `Contradictory status messages, unexplained additions to the total, or an after-sales window that is close to expiring also justify a pause. Preserve the current state, name the exact discrepancy, and request a written explanation. Unresolved uncertainty is itself decision-relevant evidence. It should not be covered by an optimistic promise, a community slogan or pressure to continue.`]],
    [`Reach a dated, limited conclusion`, [`${b.decision} This conclusion applies to the public evidence checked on 21 September 2026. It is not a purchase recommendation and does not guarantee a seller, product, customs outcome, support response or delivery. Its value comes from showing the evidence chain and the limits instead of hiding them behind a simple verdict.`, `Repeat the key checks before every sensitive action: open the domain independently, read the current term, inspect the cost stack, preserve the order record and date the result. When new evidence appears, change the conclusion only as far as the observed change supports. That keeps the article useful without turning every announcement, complaint or successful parcel into a new final judgment.`]],
  ];
}

function build(locale: Locale, b: Brief): Article {
  const read: Record<Locale,string> = { en:"15 min evidence-led report", de:"15 Min. belegbasierter Bericht", es:"Informe con evidencia · 15 min", fr:"Rapport étayé · 15 min", it:"Rapporto basato su prove · 15 min" };
  const reviewed: Record<Locale,string> = { en:"Public sources reviewed 21 Sep 2026", de:"Öffentliche Quellen geprüft am 21. Sep. 2026", es:"Fuentes públicas revisadas el 21 sep 2026", fr:"Sources publiques vérifiées le 21 sept. 2026", it:"Fonti pubbliche verificate il 21 set 2026" };
  const articleSections=sections(locale,b);
  if(locale==="en") articleSections.at(-1)?.[1].push("Recheck the live source whenever the decision date, destination or transaction stage changes.");
  return { title:b.title, tag:b.tag, lede:b.lede, read:read[locale], reviewed:reviewed[locale], sections:articleSections, sources:b.sources };
}

